1	// A per-request forwarding session. This is the sidecar's answer to the stdio
2	// server's `AgentSession`: it satisfies the same `SessionLike` shape the shared
3	// tool surface consumes, but instead of onboarding, exchanging assertions, and
4	// caching credentials `0600` on disk, it carries only the caller's already-minted
5	// OAuth bearer and attaches it to each forwarded XRPC call.
6	//
7	// It is IMMUTABLE and REQUEST-SCOPED: constructed fresh for each request, bound
8	// to that request's token at construction, and never mutated or shared. Two
9	// concurrent requests — even from the same caller — hold distinct session objects,
10	// so one can never overwrite or release the other's credential. The token lives
11	// only on the request-scoped object, which becomes unreachable once the request
12	// resolves; nothing durable is written and nothing survives a restart (ADR-0024).
13	
14	import { createHash } from 'node:crypto';
15	import type { SessionLike } from '../../mcp/src/tools.ts';
16	import { decodeJwtPayload, type SessionState } from '../../mcp/src/auth.ts';
17	
18	/**
19	 * The caller's stable identity for keying the session registry: the `sub` of
20	 * the forwarded token (the acting DID). For an opaque (non-JWT) token with no
21	 * readable subject, key by a one-way SHA-256 digest instead of the token itself,
22	 * so the raw credential is never retained — not even as a map key (ADR-0024).
23	 * Distinct tokens still map to distinct keys; the same token maps stably.
24	 */
25	export function callerSubject(token: string): string {
26	  try {
27	    const sub = decodeJwtPayload(token).sub;
28	    if (typeof sub === 'string' && sub) return sub;
29	  } catch {
30	    // Not a decodable JWT — fall through to the digest-based fallback.
31	  }
32	  return `opaque:${createHash('sha256').update(token).digest('hex')}`;
33	}
34	
35	export class ForwardingSession implements SessionLike {
36	  readonly pdsUrl: string;
37	  private readonly token: string;
38	  private readonly grantedScopes: string[];
39	
40	  constructor(pdsOrigin: string, token: string, scopes?: string[]) {
41	    this.pdsUrl = pdsOrigin;
42	    this.token = token;
43	    this.grantedScopes = scopes?.length ? scopes : scopesFromToken(token);
44	  }
45	
46	  /** The forwarded caller token — returned as-is, never exchanged or cached. */
47	  accessToken(): Promise<string> {
48	    return Promise.resolve(this.token);
49	  }
50	
51	  /** The acting DID, read from the forwarded token's subject claim. */
52	  did(): string | null {
53	    try {
54	      const sub = decodeJwtPayload(this.token).sub;
55	      return typeof sub === 'string' ? sub : null;
56	    } catch {
57	      return null;
58	    }
59	  }
60	
61	  scopes(): string[] {
62	    return this.grantedScopes;
63	  }
64	
65	  status(): SessionState {
66	    return {
67	      state: 'ready',
68	      did: this.did() ?? '(unknown)',
69	      scopes: this.grantedScopes,
70	      registrationId: null,
71	    };
72	  }
73	}
74	
75	/** Read space-delimited scopes from a token's `scope` claim, if present. */
76	function scopesFromToken(token: string): string[] {
77	  try {
78	    const scope = decodeJwtPayload(token).scope;
79	    return typeof scope === 'string' && scope ? scope.split(' ') : [];
80	  } catch {
81	    return [];
82	  }
83	}
