1	// Shared test scaffolding for the sidecar suite. The scaffold-phase tests do not
2	// need the full hermetic PDS the stdio conformance suite spawns — forwarding is
3	// asserted against a lightweight stub PDS that records the inbound requests
4	// (headers included), which is exactly what the credential-forwarding ACs call
5	// for (AC2.5). The real firehose / real OAuth handshake is Phase 3 (MM-370) and
6	// the live checks (HV-2/HV-3).
7	
8	import * as http from 'node:http';
9	import type { AddressInfo } from 'node:net';
10	import { Client } from '@modelcontextprotocol/sdk/client/index.js';
11	import { StreamableHTTPClientTransport } from '@modelcontextprotocol/sdk/client/streamableHttp.js';
12	import { createSidecar } from '../src/server.ts';
13	import { loadConfig } from '../src/config.ts';
14	import type { SessionRegistry } from '../src/registry.ts';
15	
16	/** A recorded inbound request to the stub PDS. */
17	export interface CapturedRequest {
18	  method: string;
19	  path: string;
20	  authorization: string | undefined;
21	  body: string;
22	}
23	
24	export interface StubPds {
25	  url: string;
26	  requests: CapturedRequest[];
27	  /** Force the next XRPC response (status + JSON body). Defaults to 200 + `{}`. */
28	  respondWith: (status: number, body: unknown) => void;
29	  close: () => Promise<void>;
30	}
31	
32	/** A stub PDS that records every request and returns a canned XRPC response. */
33	export function startStubPds(): Promise<StubPds> {
34	  const requests: CapturedRequest[] = [];
35	  let nextStatus = 200;
36	  let nextBody: unknown = {};
37	
38	  return new Promise((resolve) => {
39	    const server = http.createServer((req, res) => {
40	      const chunks: Buffer[] = [];
41	      req.on('data', (c) => chunks.push(c as Buffer));
42	      req.on('end', () => {
43	        requests.push({
44	          method: req.method ?? '',
45	          path: req.url ?? '',
46	          authorization: req.headers['authorization'],
47	          body: Buffer.concat(chunks).toString('utf8'),
48	        });
49	        res.writeHead(nextStatus, { 'content-type': 'application/json' });
50	        res.end(JSON.stringify(nextBody));
51	        // Reset to the default after each response so one override is one-shot.
52	        nextStatus = 200;
53	        nextBody = {};
54	      });
55	    });
56	    server.listen(0, '127.0.0.1', () => {
57	      const { port } = server.address() as AddressInfo;
58	      resolve({
59	        url: `http://127.0.0.1:${port}`,
60	        requests,
61	        respondWith: (status, body) => {
62	          nextStatus = status;
63	          nextBody = body;
64	        },
65	        close: () => new Promise((r) => server.close(() => r())),
66	      });
67	    });
68	  });
69	}
70	
71	export interface RunningSidecar {
72	  url: string;
73	  registry: SessionRegistry;
74	  close: () => Promise<void>;
75	}
76	
77	/** Build + listen the sidecar against a given PDS origin on an ephemeral port. */
78	export function startSidecar(env: Record<string, string>): Promise<RunningSidecar> {
79	  // Config parses with its default port; the test listens on an OS-assigned
80	  // ephemeral port instead (server.listen(0) below), so config.port is unused.
81	  const config = loadConfig(env as NodeJS.ProcessEnv);
82	  const { server, registry } = createSidecar(config);
83	  return new Promise((resolve) => {
84	    server.listen(0, '127.0.0.1', () => {
85	      const { port } = server.address() as AddressInfo;
86	      resolve({
87	        url: `http://127.0.0.1:${port}`,
88	        registry,
89	        close: () => new Promise((r) => server.close(() => r())),
90	      });
91	    });
92	  });
93	}
94	
95	/** Connect an MCP client over Streamable HTTP, optionally forwarding a token. */
96	export async function connectClient(sidecarUrl: string, token?: string): Promise<Client> {
97	  const client = new Client({ name: 'sidecar-test', version: '0.0.0' });
98	  const transport = new StreamableHTTPClientTransport(new URL(`${sidecarUrl}/mcp`), {
99	    requestInit: token ? { headers: { Authorization: `Bearer ${token}` } } : undefined,
100	  });
101	  await client.connect(transport);
102	  return client;
103	}
