105	/**
106	 * A syntactically valid, unsigned JWT with the given claims. `decodeJwtPayload`
107	 * reads the payload without verifying (the sidecar never verifies — the PDS is
108	 * the resource server), so this is enough to exercise DID/scope derivation and
109	 * forwarding. Never a real credential.
110	 */
111	export function fakeToken(claims: Record<string, unknown>): string {
112	  const b64 = (obj: unknown) => Buffer.from(JSON.stringify(obj)).toString('base64url');
113	  // A realistic-length signature segment so the token has the shape of a real
114	  // JWT (the redaction backstop matches JWT-shaped substrings).
115	  const signature = Buffer.from('sidecar-test-signature-placeholder').toString('base64url');
116	  return `${b64({ alg: 'ES256', typ: 'JWT' })}.${b64(claims)}.${signature}`;
117	}
118	
119	export function toolJson(result: unknown): any {
120	  const content = (result as { content: { type: string; text: string }[] }).content;
121	  return JSON.parse(content[0]!.text);
122	}
