1	// Test runner for the sidecar suite. Unlike the stdio conformance suite, these
2	// scaffold-phase tests need no TLS proxy: the sidecar and the stub PDS are both
3	// plain-HTTP loopback services, so there is no cert to generate or trust. This
4	// wrapper just runs `node --test` over the suite with TypeScript stripping's
5	// experimental warning silenced.
6	
7	import { spawnSync } from 'node:child_process';
8	import * as path from 'node:path';
9	import { fileURLToPath } from 'node:url';
10	
11	const testDir = path.dirname(fileURLToPath(import.meta.url));
12	const files = [
13	  'config.test.ts',
14	  'registry.test.ts',
15	  'redaction.test.ts',
16	  'transport.test.ts',
17	  'forwarding.test.ts',
18	  'sessions.test.ts',
19	].map((f) => path.join(testDir, f));
20	
21	const result = spawnSync(process.execPath, ['--disable-warning=ExperimentalWarning', '--test', ...files], {
22	  stdio: 'inherit',
23	  env: process.env,
24	});
25	process.exit(result.status ?? 1);
