1	// Test harness: spawns a hermetic local PDS and provisions a real account
2	// through the same ceremony the identity wallet uses, reusing the plumbing
3	// from tools/interop. plc.directory is mocked so no test traffic ever reaches
4	// the live network.
5	//
6	// The PDS requires an https public_url (RFC 8414), so each spawned instance
7	// is fronted by a loopback TLS proxy using the throwaway cert generated by
8	// test/run.ts; everything a client discovers (issuer, endpoints, resource)
9	// is the https proxy origin.
10	
11	import { spawn, type ChildProcess } from 'node:child_process';
12	import * as fs from 'node:fs';
13	import * as http from 'node:http';
14	import * as https from 'node:https';
15	import * as net from 'node:net';
16	import * as path from 'node:path';
17	import { fileURLToPath } from 'node:url';
18	
19	const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
20	
21	export const ADMIN_TOKEN = 'mcp-conformance-admin-token';
22	
23	function pdsBinary(): string {
24	  const explicit = process.env.CUSTOS_MCP_TEST_PDS_BIN;
25	  const candidates = explicit
26	    ? [explicit]
27	    : [
28	        path.join(repoRoot, 'target', 'debug', 'pds'),
29	        path.join(repoRoot, 'target', 'release', 'pds'),
30	      ];
31	  for (const candidate of candidates) {
32	    if (fs.existsSync(candidate)) return candidate;
33	  }
34	  throw new Error(
35	    `no pds binary found (looked at ${candidates.join(', ')}). ` +
36	      'Run `cargo build -p pds` first, or point CUSTOS_MCP_TEST_PDS_BIN at one.',
37	  );
38	}
39	
40	function tlsMaterial(): { key: Buffer; cert: Buffer } {
41	  const dir = process.env.CUSTOS_MCP_TEST_TLS_DIR;
42	  if (!dir) {
43	    throw new Error('CUSTOS_MCP_TEST_TLS_DIR is not set — run the suite via `pnpm test`');
44	  }
45	  return {
46	    key: fs.readFileSync(path.join(dir, 'key.pem')),
47	    cert: fs.readFileSync(path.join(dir, 'cert.pem')),
48	  };
49	}
50	
51	/** An OS-assigned free port (bind on 0, read, release) — no collision guessing. */
52	function freePort(): Promise<number> {
53	  return new Promise((resolve, reject) => {
54	    const server = net.createServer();
55	    server.listen(0, '127.0.0.1', () => {
56	      const port = (server.address() as { port: number }).port;
57	      server.close((err) => (err ? reject(err) : resolve(port)));
58	    });
59	  });
60	}
61	
62	/** A stub plc.directory that accepts every genesis op. Never touch the real one from tests. */
63	export function startMockPlc(): Promise<{ url: string; close: () => void }> {
64	  return new Promise((resolve) => {
65	    const server = http.createServer((_req, res) => {
66	      res.writeHead(200, { 'content-type': 'application/json' });
67	      res.end('{}');
68	    });
69	    server.listen(0, '127.0.0.1', () => {
70	      const address = server.address() as { port: number };
71	      resolve({ url: `http://127.0.0.1:${address.port}`, close: () => server.close() });
72	    });
73	  });
74	}
75	
76	/** TLS-terminating loopback proxy in front of a plain-http upstream. */
77	function startTlsProxy(): Promise<{
78	  port: number;
79	  setUpstreamPort: (port: number) => void;
80	  close: () => void;
81	}> {
82	  let upstreamPort = 0;
83	  return new Promise((resolve) => {
84	    const server = https.createServer(tlsMaterial(), (req, res) => {
85	      const upstream = http.request(
86	        {
87	          host: '127.0.0.1',
88	          port: upstreamPort,
89	          path: req.url,
90	          method: req.method,
91	          headers: req.headers,
92	        },
93	        (upstreamRes) => {
94	          res.writeHead(upstreamRes.statusCode ?? 502, upstreamRes.headers);
95	          upstreamRes.pipe(res);
96	        },
97	      );
98	      upstream.on('error', (err) => {
99	        res.writeHead(502, { 'content-type': 'text/plain' });
100	        res.end(`proxy error: ${err.message}`);
101	      });
102	      req.pipe(upstream);
103	    });
104	    server.listen(0, '127.0.0.1', () => {
105	      const address = server.address() as { port: number };
106	      resolve({
107	        port: address.port,
108	        setUpstreamPort: (port) => (upstreamPort = port),
109	        close: () => server.close(),
110	      });
111	    });
112	  });
113	}
114	
115	export interface SpawnedPds {
116	  /** The https origin clients use — also the PDS's configured public_url. */
117	  baseUrl: string;
118	  proc: ChildProcess;
119	  dataDir: string;
120	  stop: () => void;
121	}
122	
123	/**
124	 * Spawn the pds binary configured entirely from env vars (cwd points at an
125	 * empty dir so no pds.toml is picked up), fronted by a TLS proxy, and wait
126	 * for /xrpc/_health.
127	 */
128	export async function spawnPds(options: {
129	  dir: string;
130	  plcUrl: string;
131	  agentAuthEnabled: boolean;
132	}): Promise<SpawnedPds> {
133	  const proxy = await startTlsProxy();
134	  const httpPort = await freePort();
135	  proxy.setUpstreamPort(httpPort);
136	  const baseUrl = `https://127.0.0.1:${proxy.port}`;
137	  const dataDir = path.join(options.dir, 'data');
138	  fs.mkdirSync(dataDir, { recursive: true });
139	
140	  const proc = spawn(pdsBinary(), [], {
141	    cwd: options.dir,
142	    env: {
143	      PATH: process.env.PATH ?? '',
144	      EZPDS_DATA_DIR: dataDir,
145	      EZPDS_DATABASE_URL: path.join(dataDir, 'pds.db'),
146	      EZPDS_BIND_ADDRESS: '127.0.0.1',
147	      EZPDS_PORT: String(httpPort),
148	      EZPDS_PUBLIC_URL: baseUrl,
149	      EZPDS_AVAILABLE_USER_DOMAINS: 'localhost',
150	      EZPDS_ADMIN_TOKEN: ADMIN_TOKEN,
151	      EZPDS_PLC_DIRECTORY_URL: options.plcUrl,
152	      // Throwaway: encrypts per-account repo signing keys in the test DB.
153	      EZPDS_SIGNING_KEY_MASTER_KEY: '00'.repeat(32),
154	      EZPDS_RATE_LIMIT_ENABLED: 'false',
155	      EZPDS_AGENT_AUTH_SERVICE_AUTH_ENABLED: options.agentAuthEnabled ? 'true' : 'false',
156	    },
157	    stdio: ['ignore', 'pipe', 'pipe'],
158	  });
159	  const logs: string[] = [];
160	  proc.stdout!.on('data', (chunk) => logs.push(String(chunk)));
161	  proc.stderr!.on('data', (chunk) => logs.push(String(chunk)));
162	
163	  const deadline = Date.now() + 30_000;
164	  for (;;) {
165	    if (proc.exitCode !== null) {
166	      proxy.close();
167	      throw new Error(`pds exited with ${proc.exitCode} during startup:\n${logs.join('')}`);
168	    }
169	    try {
170	      const res = await fetch(`http://127.0.0.1:${httpPort}/xrpc/_health`, {
171	        signal: AbortSignal.timeout(2_000),
172	      });
173	      if (res.ok) break;
174	    } catch {
175	      // not up yet
176	    }
177	    if (Date.now() > deadline) {
178	      proc.kill();
179	      proxy.close();
180	      throw new Error(`pds did not become healthy within 30s:\n${logs.join('')}`);
181	    }
182	    await new Promise((r) => setTimeout(r, 200));
183	  }
184	
185	  return {
186	    baseUrl,
187	    proc,
188	    dataDir,
189	    stop: () => {
190	      proc.kill();
191	      proxy.close();
192	    },
193	  };
194	}
