196	export interface TestAccount {
197	  did: string;
198	  handle: string;
199	  email: string;
200	  accessJwt: string;
201	}
202	
203	/**
204	 * Provision a full account (claim code → mobile account → repo signing key →
205	 * client-signed did:plc genesis → handle → session) by reusing
206	 * tools/interop's account ceremony against the spawned PDS.
207	 */
208	export async function provisionAccount(baseUrl: string, stateDir: string): Promise<TestAccount> {
209	  // interop's config module reads these at first import, so they must be set
210	  // before the dynamic import below.
211	  process.env.EZPDS_BASE_URL = baseUrl;
212	  process.env.EZPDS_ADMIN_TOKEN = ADMIN_TOKEN;
213	  process.env.EZPDS_INTEROP_STATE_DIR = stateDir;
214	  process.env.EZPDS_INTEROP_PACE_MS = '25';
215	
216	  const account = await import('ezpds-interop/src/account.js');
217	  const created = await account.createAccount({ name: 'mcp-conformance', kind: 'ephemeral' });
218	  return {
219	    did: created.did,
220	    handle: created.handle,
221	    email: created.email,
222	    accessJwt: created.accessJwt,
223	  };
224	}
