226	/** The human half of the ceremony: confirm the claim code as the account owner. */
227	export async function confirmClaim(
228	  baseUrl: string,
229	  ownerAccessJwt: string,
230	  userCode: string,
231	): Promise<void> {
232	  const res = await fetch(`${baseUrl}/agent/identity/claim/confirm`, {
233	    method: 'POST',
234	    headers: {
235	      'content-type': 'application/json',
236	      authorization: `Bearer ${ownerAccessJwt}`,
237	    },
238	    body: JSON.stringify({ user_code: userCode }),
239	  });
240	  const body = (await res.json()) as { status?: string };
241	  if (!res.ok) {
242	    throw new Error(`claim confirm failed (${res.status}): ${JSON.stringify(body)}`);
243	  }
244	  if (body.status !== 'claimed') {
245	    throw new Error(`unexpected claim confirm status: ${JSON.stringify(body)}`);
246	  }
247	}
