1	// Account provisioning + session management against the ezpds provisioning API
2	// and standard XRPC session endpoints.
3	//
4	// Flow (mirrors the identity-wallet mobile ceremony):
5	//   1. admin claim code            POST /v1/accounts/claim-codes   (admin token)
6	//   2. pending mobile account      POST /v1/accounts/mobile
7	//   3. PDS-issued repo signing key GET  /v1/repo-signing-key       (session token)
8	//   4. client-signed did:plc genesis op → POST /v1/dids
9	//   5. handle registration         POST /v1/handles
10	//   6. standard session            POST /xrpc/com.atproto.server.createSession
11	
12	import { BASE_URL, ADMIN_TOKEN, defaultEmail } from './config.js';
13	import { request, xrpc } from './http.js';
14	import { newKeypair, keypairFromHex, buildGenesisOp, randomPassword, randomSuffix } from './crypto.js';
15	import { loadState, saveState, getAccount } from './state.js';
16	
17	export async function describeServer() {
18	  return xrpc(BASE_URL, 'com.atproto.server.describeServer');
19	}
20	
21	export async function health() {
22	  return xrpc(BASE_URL, '_health');
23	}
24	
25	export async function mintClaimCode() {
26	  if (!ADMIN_TOKEN) {
27	    throw new Error('EZPDS_ADMIN_TOKEN is not set — cannot mint a claim code. Either export it or pass --claim-code.');
28	  }
29	  const data = await request(`${BASE_URL}/v1/accounts/claim-codes`, {
30	    method: 'POST',
31	    token: ADMIN_TOKEN,
32	    body: { count: 1, expiresInHours: 1 },
33	  });
34	  return data.codes[0];
35	}
36	
37	/**
38	 * Create a fully provisioned account and persist its credentials in state.
39	 *
40	 * @param {{name: string, kind: 'persistent'|'ephemeral', handle?: string, claimCode?: string}} opts
41	 */
42	export async function createAccount({ name, kind, handle, claimCode }) {
43	  const state = loadState();
44	  if (state.accounts[name]) {
45	    throw new Error(`account "${name}" already exists in state (did: ${state.accounts[name].did}). Pick another --name or delete it first.`);
46	  }
47	
48	  if (!handle) {
49	    const server = await describeServer();
50	    const domains = server.availableUserDomains ?? [];
51	    if (!domains.length) throw new Error('describeServer returned no availableUserDomains; pass --handle explicitly');
52	    const domain = domains[0].replace(/^\./, '');
53	    handle = `${name.replace(/[^a-z0-9-]/gi, '-').toLowerCase()}-${randomSuffix(4)}.${domain}`;
54	  }
55	
56	  const email = defaultEmail(name);
57	  const password = randomPassword();
58	  const code = claimCode ?? await mintClaimCode();
59	
60	  console.log(`creating ${kind} account "${name}" — handle ${handle}`);
61	
62	  // Device key: identifies this CLI as the account's "device".
63	  const deviceKey = await newKeypair();
64	  const mobile = await request(`${BASE_URL}/v1/accounts/mobile`, {
65	    method: 'POST',
66	    body: {
67	      email,
68	      handle,
69	      devicePublicKey: deviceKey.publicKeyBase64,
70	      platform: 'ios',
71	      claimCode: code,
72	    },
73	  });
74	
75	  // Persist as soon as the remote side-effect exists: a failure in any later
76	  // ceremony step must leave a recoverable trace (tokens included) instead of
77	  // an orphaned server-side account that a retry would silently duplicate.
78	  const persist = (fields) => {
79	    state.accounts[name] = { ...(state.accounts[name] ?? {}), ...fields };
80	    saveState(state);
81	    return state.accounts[name];
82	  };
83	  persist({
84	    kind,
85	    name,
86	    handle,
87	    email,
88	    password,
89	    provisioningStatus: 'mobile-created',
90	    accountId: mobile.accountId,
91	    deviceKeyId: deviceKey.keyId,
92	    deviceKeyPrivateHex: deviceKey.privateKeyHex,
93	    deviceToken: mobile.deviceToken,
94	    pendingSessionToken: mobile.sessionToken,
95	    createdAt: new Date().toISOString(),
96	  });
97	
98	  // PDS-issued per-account repo signing key: rotationKeys[1] + verificationMethods.atproto.
99	  const repoKey = await request(`${BASE_URL}/v1/repo-signing-key`, { token: mobile.sessionToken });
100	
101	  // Rotation key: held locally, signs the genesis op — the root of control.
102	  const rotationKey = await newKeypair();
103	  const { did, signedOp } = await buildGenesisOp({
