158	function jwtExpiresSoon(jwt, marginSeconds = 60) {
159	  try {
160	    const payload = JSON.parse(Buffer.from(jwt.split('.')[1], 'base64url').toString('utf8'));
161	    return payload.exp * 1000 < Date.now() + marginSeconds * 1000;
162	  } catch {
163	    return true;
