167	/**
168	 * Return a valid accessJwt for the named account, refreshing (or as a last
169	 * resort re-authenticating) only when needed — createSession is rate-limited
170	 * to 30/5min per IP, so sessions are reused aggressively.
171	 */
172	export async function ensureSession(name) {
173	  const state = loadState();
174	  const account = getAccount(state, name);
175	
176	  if (account.accessJwt && !jwtExpiresSoon(account.accessJwt)) return account;
177	
178	  if (account.refreshJwt && !jwtExpiresSoon(account.refreshJwt)) {
179	    try {
180	      const refreshed = await xrpc(BASE_URL, 'com.atproto.server.refreshSession', {
181	        method: 'POST',
182	        token: account.refreshJwt,
183	      });
184	      account.accessJwt = refreshed.accessJwt;
185	      account.refreshJwt = refreshed.refreshJwt;
186	      saveState(state);
187	      return account;
188	    } catch {
189	      // fall through to createSession
190	    }
191	  }
192	
193	  const session = await xrpc(BASE_URL, 'com.atproto.server.createSession', {
194	    method: 'POST',
195	    body: { identifier: account.did, password: account.password },
196	  });
197	  account.accessJwt = session.accessJwt;
198	  account.refreshJwt = session.refreshJwt;
199	  saveState(state);
200	  return account;
201	}
