203	/**
204	 * Tear down an ephemeral account: deactivate it with a deleteAfter a few
205	 * minutes out; the server-side reaper then permanently purges it (repo, blobs,
206	 * sessions, handle) and broadcasts #account status=deleted so relays drop it.
207	 * The did:plc entry remains on plc.directory per ezpds's wallet-native model.
208	 */
209	export async function scheduleEphemeralDeletion(name, { afterMinutes = 5 } = {}) {
210	  const state = loadState();
211	  const account = getAccount(state, name);
212	  if (account.kind !== 'ephemeral') {
213	    throw new Error(`account "${name}" is ${account.kind}, not ephemeral — refusing to schedule deletion`);
214	  }
215	  const live = await ensureSession(name);
216	  const deleteAfter = new Date(Date.now() + afterMinutes * 60_000).toISOString();
217	  await xrpc(BASE_URL, 'com.atproto.server.deactivateAccount', {
218	    method: 'POST',
219	    token: live.accessJwt,
220	    body: { deleteAfter },
221	  });
222	  account.scheduledDeletion = deleteAfter;
223	  saveState(state);
224	  console.log(`ephemeral account "${name}" deactivated; server reaper will purge it after ${deleteAfter}`);
225	  return deleteAfter;
226	}
