1	// P-256 key handling and did:plc genesis-op construction. ezpds never mints a
2	// server-custodied DID: the client builds and signs the genesis operation itself
3	// (rotationKeys[0] = our locally-held rotation key), so the private keys the CLI
4	// generates here are the real root of control for test accounts — they are
5	// persisted in the local state file and must never be committed.
6	
7	import * as crypto from 'node:crypto';
8	import * as dagCbor from '@ipld/dag-cbor';
9	import { P256Keypair } from '@atproto/crypto';
10	
11	const BASE32_ALPHABET = 'REDACTED';
12	
13	function base32Encode(buffer) {
14	  let result = '';
15	  let bits = 0;
16	  let value = 0;
17	  for (const byte of buffer) {
18	    value = (value << 8) | byte;
19	    bits += 8;
20	    while (bits >= 5) {
21	      result += BASE32_ALPHABET[(value >>> (bits - 5)) & 0x1f];
22	      bits -= 5;
23	    }
24	  }
25	  if (bits > 0) result += BASE32_ALPHABET[(value << (5 - bits)) & 0x1f];
26	  return result;
27	}
