47	/**
48	 * Sign a did:plc operation (genesis or migration) with a rotation keypair.
49	 *
50	 * The signing primitive shared by every PLC op: DAG-CBOR encode the unsigned op,
51	 * sign those bytes with the rotation key, and append the signature as base64url.
52	 * Returns the signed op (all unsigned fields plus `sig`). This is the single
53	 * source of truth for PLC signing — genesis and migration both consume it, so
54	 * the two paths cannot silently diverge.
55	 */
56	export async function signPlcOp(unsignedOp, rotationKeypair) {
57	  const unsignedBytes = dagCbor.encode(unsignedOp);
58	  const signature = await rotationKeypair.sign(unsignedBytes);
59	  return { ...unsignedOp, sig: Buffer.from(signature).toString('base64url') };
60	}
61	
62	/**
63	 * Build and sign a did:plc genesis operation.
64	 *
65	 * rotationKeys[0] = the locally-held rotation key (signs this op),
66	 * rotationKeys[1] = the PDS-issued per-account repo signing key, which is also
67	 * verificationMethods.atproto (it signs repo commits on the PDS).
68	 *
69	 * Returns the derived DID (`did:plc:` + first 24 chars of base32(sha256(signed
70	 * op DAG-CBOR))) and the signed op as a JSON-ready object.
71	 */
72	export async function buildGenesisOp({ rotationKeyId, repoSigningKeyId, rotationKeypair, handle, pdsUrl }) {
73	  const unsignedOp = {
74	    prev: null,
75	    type: 'plc_operation',
76	    services: {
77	      atproto_pds: {
78	        type: 'AtprotoPersonalDataServer',
79	        endpoint: pdsUrl,
80	      },
81	    },
82	    alsoKnownAs: [`at://${handle}`],
83	    rotationKeys: [rotationKeyId, repoSigningKeyId],
84	    verificationMethods: {
85	      atproto: repoSigningKeyId,
86	    },
87	  };
88	
89	  const signedOp = await signPlcOp(unsignedOp, rotationKeypair);
90	
91	  const signedBytes = dagCbor.encode(signedOp);
92	  const hash = crypto.createHash('sha256').update(signedBytes).digest();
93	  const did = `did:plc:${base32Encode(hash).slice(0, 24)}`;
94	
95	  return { did, signedOp };
96	}
