103	/** Short random suffix for handles/names. */
104	export function randomSuffix(len = 6) {
105	  return crypto.randomBytes(8).toString('base64url').replace(/[^a-z0-9]/gi, '').toLowerCase().slice(0, len).padEnd(len, '0');
106	}
