37	const ANONYMOUS_RESERVE_SIGNING_KEY_LIMIT: &str = "reserveSigningKey:<anonymous>";
38	
39	pub async fn reserve_signing_key(
40	    State(state): State<AppState>,
41	    remote_addr: Result<ConnectInfo<SocketAddr>, ExtensionRejection>,
42	    Json(request): Json<ReserveSigningKeyRequest>,
43	) -> Result<Json<ReserveSigningKeyResponse>, ApiError> {
44	    // axum 0.8 dropped the blanket `Option<T>` extractor; `Result` keeps the same
45	    // "absent under `oneshot` test harnesses" tolerance ConnectInfo needs here.
46	    let remote_addr = remote_addr.ok();
47	    let did = request
48	        .did
49	        .as_deref()
50	        .map(str::trim)
51	        .filter(|did| !did.is_empty());
52	    if let Some(did) = did {
53	        validate_did(did)?;
54	        if let Some(existing) = get_reserved_repo_key_by_did(&state.db, did)
55	            .await
56	            .map_err(|e| {
57	                tracing::error!(error = %e, did = %did, "failed to read reserved signing key");
58	                ApiError::new(ErrorCode::InternalError, "failed to read signing key")
59	            })?
60	        {
61	            return Ok(Json(ReserveSigningKeyResponse {
62	                signing_key: existing.key_id,
63	            }));
64	        }
65	    }
66	
67	    check_anonymous_reservation_limit(&state, remote_addr.as_ref())?;
68	
69	    let key = generate_reserved_key(&state)?;
70	    let inserted = insert_reserved_repo_key(&state.db, did, &key)
71	        .await
72	        .map_err(|e| {
73	            tracing::error!(error = %e, did = ?did, "failed to store reserved signing key");
74	            ApiError::new(ErrorCode::InternalError, "failed to store signing key")
75	        })?;
76	
77	    if !inserted {
78	        let did = did.ok_or_else(|| {
79	            tracing::error!("reserved signing-key insert conflicted without a DID");
80	            ApiError::new(ErrorCode::InternalError, "failed to reserve signing key")
81	        })?;
82	        let existing = get_reserved_repo_key_by_did(&state.db, did)
83	            .await
84	            .map_err(|e| {
85	                tracing::error!(error = %e, did = %did, "failed to read conflicted reserved signing key");
86	                ApiError::new(ErrorCode::InternalError, "failed to read signing key")
87	            })?
88	            .ok_or_else(|| {
89	                tracing::error!(did = %did, "reserved signing-key conflict row disappeared");
90	                ApiError::new(ErrorCode::InternalError, "failed to reserve signing key")
91	            })?;
92	        return Ok(Json(ReserveSigningKeyResponse {
93	            signing_key: existing.key_id,
94	        }));
95	    }
96	
97	    Ok(Json(ReserveSigningKeyResponse {
98	        signing_key: key.key_id,
99	    }))
100	}
