1	// The MCP tool surface: a deliberately small set matching the default agent
2	// scope profile (repo create/update + blob upload + AppView reads). Every tool
3	// runs as the agent registration the user confirmed — writes are attributed to
4	// it and visible in the user's audit log.
5	//
6	// put_record and delete_record are registered only when the operator sets
7	// CUSTOS_MCP_ALLOW_DESTRUCTIVE; with it unset they do not appear in the tool
8	// list at all.
9	
10	import * as fs from 'node:fs';
11	import * as path from 'node:path';
12	import { z } from 'zod';
13	import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
14	import type { AuthInfo } from '@modelcontextprotocol/sdk/server/auth/types.js';
15	import { xrpc, HttpError } from './http.ts';
16	import { RevokedError, SessionExpiredError, type SessionState } from './auth.ts';
17	import { ALLOW_DESTRUCTIVE, imageDir } from './config.ts';
18	
19	/**
20	 * The slice of a session the tool surface actually consumes. `AgentSession`
21	 * (the stdio server's onboarding-and-cache unit) satisfies it structurally, and
22	 * so does the sidecar's per-request forwarding session — that is what lets both
23	 * entry points single-source these tool implementations.
24	 */
25	export interface SessionLike {
26	  readonly pdsUrl: string;
27	  accessToken(): Promise<string>;
28	  did(): string | null;
29	  scopes(): string[];
30	  status(): SessionState;
31	}
32	
33	/**
34	 * Resolves the session a tool call runs as. The stdio server binds one
35	 * singleton (`() => session`); the sidecar resolves a per-caller forwarding
36	 * session from the request's authenticated identity (`extra.authInfo`). A tool
37	 * handler is invoked with the MCP `extra` object, which carries `authInfo` when
38	 * the transport authenticated the caller.
39	 */
40	export type SessionResolver = (extra?: { authInfo?: AuthInfo }) => SessionLike;
41	
42	const ATTRIBUTION =
43	  'Runs as this MCP server’s agent registration: the action is attributed to the agent ' +
44	  'and visible in the account owner’s audit log.';
45	
46	type ToolResult = {
47	  content: { type: 'text'; text: string }[];
48	  isError?: boolean;
49	};
50	
51	function ok(data: unknown): ToolResult {
52	  return { content: [{ type: 'text', text: JSON.stringify(data, null, 2) }] };
53	}
54	
55	function fail(message: string): ToolResult {
56	  return { content: [{ type: 'text', text: message }], isError: true };
57	}
58	
59	/**
60	 * Translate transport/PDS failures into messages an MCP client can act on —
61	 * never a stack trace. Scope refusals name the missing permission and the
62	 * scopes the agent actually holds.
63	 */
64	function relayError(err: unknown, session: SessionLike): ToolResult {
65	  if (err instanceof RevokedError || err instanceof SessionExpiredError) {
66	    return fail(err.message);
67	  }
68	  if (err instanceof HttpError) {
69	    if (err.status === 403 && err.errorCode === 'InsufficientScope') {
70	      const scopes = session.scopes();
71	      return fail(
72	        `The PDS refused this action as outside the agent's granted scopes ` +
73	          `(403 InsufficientScope): ${err.errorDescription ?? 'no details'}. ` +
74	          `Granted scopes: ${scopes.length ? scopes.join(' ') : '(none recorded)'}. ` +
75	          `Widening what this agent may do requires the PDS operator to change ` +
76	          `[agent_auth] granted_scopes and the owner to re-confirm a claim ceremony.`,
77	      );
78	    }
79	    return fail(
80	      `The PDS rejected the request (HTTP ${err.status}` +
81	        `${err.errorCode ? `, ${err.errorCode}` : ''}): ` +
82	        `${err.errorDescription ?? 'no details provided'}`,
83	    );
84	  }
85	  return fail(err instanceof Error ? err.message : String(err));
86	}
87	
88	/**
89	 * Confine image reads to the operator-configured directory. Without this, a
90	 * tool call influenced by untrusted content could publish any file the
91	 * process can read. Realpaths on both sides so symlinks cannot escape.
92	 */
93	function resolveImagePath(userPath: string): string {
94	  const configured = imageDir();
95	  if (!configured) {
96	    throw new Error(
97	      'image attachments are disabled: set CUSTOS_MCP_IMAGE_DIR to the one directory ' +
98	        'images may be read from',
99	    );
100	  }
101	  const base = fs.realpathSync(path.resolve(configured));
102	  let resolved: string;
103	  try {
104	    resolved = fs.realpathSync(path.resolve(base, userPath));
105	  } catch {
106	    throw new Error(`image_path does not exist under ${base}`);
107	  }
108	  if (resolved !== base && !resolved.startsWith(base + path.sep)) {
109	    throw new Error(`image_path must be inside ${base}`);
110	  }
111	  return resolved;
112	}
113	
114	/** MIME type for uploaded post images, by file extension. */
115	function imageMime(filePath: string): string {
116	  const mime: Record<string, string> = {
117	    '.png': 'image/png',
118	    '.jpg': 'image/jpeg',
119	    '.jpeg': 'image/jpeg',
120	    '.gif': 'image/gif',
121	    '.webp': 'image/webp',
122	  };
123	  const ext = path.extname(filePath).toLowerCase();
124	  const type = mime[ext];
125	  if (!type) {
126	    throw new Error(`unsupported image type "${ext}" — use png, jpg, gif, or webp`);
127	  }
128	  return type;
129	}
130	
131	async function requireDid(session: SessionLike): Promise<{ token: string; did: string }> {
132	  const token = await session.accessToken();
133	  const did = session.did();
134	  if (!did) throw new Error('the agent session has no DID — onboarding did not complete');
135	  return { token, did };
136	}
