415	        const result = await xrpc(session.pdsUrl, 'com.atproto.repo.deleteRecord', {
416	          method: 'POST',
417	          token,
418	          body: { repo: did, collection: args.collection, rkey: args.rkey },
419	        });
420	        return ok(result ?? { deleted: true });
