2	//
3	//   discover   GET /.well-known/oauth-protected-resource → AS metadata → auth.md
4	//   register   POST {identity_endpoint}  type=service_auth, login_hint=<email>
5	//   claim      surface user_code + verification_uri to the human, then poll
6	//              POST {token_endpoint}  grant_type=urn:workos:agent-auth:grant-type:claim
7	//   exchange   POST {token_endpoint}  grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer
