27	/** Thrown when the server says this registration was revoked. */
28	export class RevokedError extends Error {
29	  constructor() {
30	    super(
31	      'This agent was revoked in Obsign. It will not re-register itself: to onboard again, ' +
32	        'the account owner must run `custos-mcp reset` (or delete the cached-credentials file) ' +
33	        'and restart the server, then confirm the new claim ceremony.',
34	    );
35	  }
36	}
