38	/** Thrown when the identity assertion has expired and a new ceremony is needed. */
39	export class SessionExpiredError extends Error {
40	  constructor() {
41	    super(
42	      'The agent session has expired (the identity assertion outlived its TTL). ' +
43	        'A new claim ceremony has to be confirmed by the account owner — restart the ' +
44	        'MCP server to begin one, or call the whoami tool after restart for the claim code.',
