59	/** Decode a JWT payload without verifying — we only read our own credentials. */
60	export function decodeJwtPayload(jwt: string): Record<string, unknown> {
61	  const part = jwt.split('.')[1];
62	  if (!part) throw new Error('malformed JWT');
63	  return JSON.parse(Buffer.from(part, 'base64url').toString('utf8'));
64	}
