66	/**
67	 * The discovery walk from the auth.md spec: PRM names the authorization
68	 * server, its metadata carries the agent_auth block, which points at the
69	 * auth.md skill document and the agent endpoints.
70	 */
71	export async function discover(pdsUrl: string): Promise<Discovery> {
72	  const prm = await request(`${pdsUrl}/.well-known/oauth-protected-resource`);
73	  const authorizationServer: string = (prm.authorization_servers?.[0] ?? pdsUrl).replace(
74	    /\/+$/,
75	    '',
76	  );
77	
78	  const as = await request(`${authorizationServer}/.well-known/oauth-authorization-server`);
79	  const agentAuth = as.agent_auth;
80	  if (!agentAuth || !agentAuth.identity_endpoint) {
81	    throw new Error(
82	      `${pdsUrl} does not advertise agent authentication (no agent_auth block in its ` +
83	        'authorization-server metadata). This PDS cannot onboard agents via auth.md.',
84	    );
85	  }
86	
87	  return {
88	    authorizationServer,
89	    tokenEndpoint: as.token_endpoint,
90	    identityEndpoint: agentAuth.identity_endpoint,
91	    claimEndpoint: agentAuth.claim_endpoint,
92	    skill: agentAuth.skill ?? null,
93	    identityTypesSupported: agentAuth.identity_types_supported ?? [],
94	  };
