105	/**
106	 * Register via the service_auth flow (email as login_hint). The server starts
107	 * a claim ceremony bound to the matching local account and hands back the
108	 * user_code the human must confirm.
109	 */
110	export async function registerServiceAuth(
111	  discovery: Discovery,
112	  email: string,
113	): Promise<RegistrationResult> {
114	  let response;
115	  try {
116	    response = await request(discovery.identityEndpoint, {
117	      method: 'POST',
118	      body: { type: 'service_auth', login_hint: email },
119	    });
120	  } catch (err) {
121	    if (err instanceof HttpError && err.errorCode?.endsWith('_not_enabled')) {
122	      throw new Error(
123	        `This PDS has the ${err.errorCode.replace('_not_enabled', '')} agent registration ` +
124	          `flow disabled (${err.errorCode}). Ask the operator to enable ` +
125	          `[agent_auth] service_auth_enabled, or check auth.md at ` +
126	          `${discovery.skill ?? 'the service root'} for supported flows.`,
127	      );
128	    }
129	    if (err instanceof HttpError && err.errorCode === 'access_denied') {
130	      throw new Error(
131	        `The PDS rejected registration: ${err.errorDescription ?? 'access denied'}. ` +
132	          `Check that CUSTOS_MCP_EMAIL (${email}) matches an account on this PDS.`,
133	      );
134	    }
135	    throw err;
136	  }
137	
138	  return {
139	    registrationId: response.registration_id,
140	    claimToken: response.claim_token,
141	    userCode: response.claim.user_code,
142	    verificationUri: response.claim.verification_uri,
143	    expiresAt: response.claim.expires_at,
144	  };
145	}
