147	export interface ClaimGrantResult {
148	  accessToken: string;
149	  expiresIn: number;
150	  scope: string;
151	  assertion: string;
152	  assertionExpires: string;
153	}
154	
155	/**
156	 * Poll the token endpoint with the claim grant until the human confirms.
157	 * Device-flow etiquette: wait `interval` between polls, add 5s on slow_down,
158	 * cap the backoff.
159	 */
160	export async function pollClaim(
161	  discovery: Discovery,
162	  claimToken: string,
163	  options: { intervalSecs?: number; onPending?: () => void } = {},
164	): Promise<ClaimGrantResult> {
165	  let interval = (options.intervalSecs ?? 5) * 1000;
166	  const maxInterval = 60_000;
167	
168	  for (;;) {
169	    await sleep(interval);
170	    try {
171	      const token = await request(discovery.tokenEndpoint, {
172	        method: 'POST',
173	        body: new URLSearchParams({ grant_type: CLAIM_GRANT, claim_token: claimToken }),
174	      });
175	      return {
176	        accessToken: token.access_token,
177	        expiresIn: token.expires_in,
178	        scope: token.scope ?? '',
179	        assertion: token.identity_assertion,
180	        assertionExpires: token.assertion_expires,
181	      };
182	    } catch (err) {
183	      if (!(err instanceof HttpError)) throw err;
184	      switch (err.errorCode) {
185	        case 'authorization_pending':
186	          options.onPending?.();
187	          continue;
188	        case 'slow_down':
189	          interval = Math.min(interval + 5_000, maxInterval);
190	          continue;
191	        case 'expired_token':
192	          throw new Error(
193	            'The claim ceremony expired before it was confirmed. Restart the MCP server ' +
194	              'to begin a new one.',
195	          );
196	        case 'access_denied':
197	          throw new RevokedError();
198	        default:
199	          throw err;
200	      }
201	    }
202	  }
203	}
