205	/**
206	 * Exchange the identity assertion for a fresh access token (RFC 7523
207	 * JWT-bearer grant). The token inherits the assertion's scopes verbatim.
208	 */
209	export async function exchangeAssertion(
210	  tokenEndpoint: string,
211	  assertion: string,
212	  resource: string,
213	): Promise<{ accessToken: string; expiresIn: number; scope: string }> {
214	  try {
215	    const token = await request(tokenEndpoint, {
216	      method: 'POST',
217	      body: new URLSearchParams({
218	        grant_type: JWT_BEARER_GRANT,
219	        assertion,
220	        resource: `${resource}/`,
221	      }),
222	    });
223	    return {
224	      accessToken: token.access_token,
225	      expiresIn: token.expires_in,
226	      scope: token.scope ?? '',
227	    };
228	  } catch (err) {
229	    if (err instanceof HttpError) {
230	      if (err.errorCode === 'access_denied') throw new RevokedError();
231	      if (err.errorCode === 'invalid_grant') throw new SessionExpiredError();
232	    }
233	    throw err;
234	  }
235	}
