237	export type SessionState =
238	  | { state: 'onboarding'; userCode: string; verificationUri: string; expiresAt: string }
239	  | { state: 'ready'; did: string; scopes: string[]; registrationId: string | null }
240	  | { state: 'revoked' }
241	  | { state: 'expired' }
242	  | { state: 'error'; message: string };
243	
244	/**
245	 * One agent session against one PDS. Owns the cached credentials, runs the
246	 * onboarding ceremony when there are none, and hands out a live access token
247	 * to the tool layer (re-exchanging the assertion transparently).
248	 */
249	export class AgentSession {
250	  readonly pdsUrl: string;
251	  private discovery: Discovery | null = null;
252	  private creds: CachedCredentials | null;
253	  private onboarding: RegistrationResult | null = null;
254	  private onboardingError: string | null = null;
255	
256	  constructor(pdsUrl: string) {
257	    this.pdsUrl = pdsUrl;
258	    this.creds = loadCredentials(pdsUrl);
259	  }
260	
261	  private async discovered(): Promise<Discovery> {
262	    this.discovery ??= await discover(this.pdsUrl);
263	    return this.discovery;
264	  }
265	
266	  /** True if the assertion in the cache is present and unexpired. */
267	  private assertionValid(): boolean {
268	    if (!this.creds?.assertion) return false;
269	    try {
270	      const exp = decodeJwtPayload(this.creds.assertion).exp;
271	      return typeof exp === 'number' && exp * 1000 > Date.now() + 10_000;
272	    } catch {
273	      return false;
274	    }
275	  }
276	
277	  status(): SessionState {
278	    if (this.creds?.revoked) return { state: 'revoked' };
279	    if (this.onboarding) {
280	      return {
281	        state: 'onboarding',
282	        userCode: this.onboarding.userCode,
283	        verificationUri: this.onboarding.verificationUri,
284	        expiresAt: this.onboarding.expiresAt,
285	      };
286	    }
287	    if (this.onboardingError) return { state: 'error', message: this.onboardingError };
288	    if (this.assertionValid()) {
289	      return {
290	        state: 'ready',
291	        did: this.creds!.did ?? '(unknown)',
292	        scopes: this.creds!.scopes ?? [],
293	        registrationId: this.creds!.registrationId ?? null,
294	      };
295	    }
296	    if (this.creds?.assertion) return { state: 'expired' };
297	    return { state: 'error', message: 'not onboarded yet' };
298	  }
299	
300	  /** Whether startup needs to run a claim ceremony. */
301	  needsOnboarding(): boolean {
302	    return !this.creds?.revoked && !this.assertionValid();
303	  }
304	
305	  /**
306	   * Run registration (fails fast and legibly when the PDS has agent auth
307	   * disabled), then poll for the human confirmation in the background.
308	   * Returns after registration; `onReady`/`onFailed` fire from the poll loop.
309	   */
310	  async startOnboarding(callbacks: {
311	    onWaiting: (reg: RegistrationResult) => void;
312	    onReady: (state: SessionState) => void;
313	    onFailed: (err: Error) => void;
314	  }): Promise<void> {
315	    const email = loginEmail();
316	    if (!email) {
317	      throw new Error(
318	        'CUSTOS_MCP_EMAIL is not set. First-run onboarding registers this agent against ' +
319	          'your account by email — set it in the MCP server config (see tools/mcp/README.md).',
320	      );
321	    }
322	
323	    const discovery = await this.discovered();
324	    // Complete the spec's discovery walk: the skill document is the prose
325	    // half of the contract. We don't parse it, but a server that fails to
326	    // serve it is worth flagging before we register.
327	    if (discovery.skill) {
328	      try {
329	        await request(discovery.skill);
330	      } catch (err) {
331	        process.stderr.write(
332	          `[custos-mcp] warning: ${discovery.skill} is advertised but not readable ` +
333	            `(${err instanceof Error ? err.message : err})\n`,
334	        );
335	      }
336	    }
337	    const registration = await registerServiceAuth(discovery, email);
338	    this.onboarding = registration;
339	    this.onboardingError = null;
340	    callbacks.onWaiting(registration);
341	
342	    void pollClaim(discovery, registration.claimToken)
343	      .then((granted) => {
344	        const payload = decodeJwtPayload(granted.assertion);
345	        this.creds = {
346	          pdsUrl: this.pdsUrl,
347	          registrationId: registration.registrationId,
348	          assertion: granted.assertion,
349	          accessToken: granted.accessToken,
350	          accessTokenExpiresAt: Math.floor(Date.now() / 1000) + granted.expiresIn,
351	          scopes: granted.scope ? granted.scope.split(' ') : [],
352	          did: typeof payload.sub === 'string' ? payload.sub : undefined,
353	        };
354	        saveCredentials(this.creds);
355	        this.onboarding = null;
356	        callbacks.onReady(this.status());
357	      })
358	      .catch((err: Error) => {
359	        this.onboarding = null;
360	        if (err instanceof RevokedError) {
361	          // A revocation mid-ceremony (the owner declined) is remembered even
362	          // with no prior credential cache, so a restart cannot quietly start
363	          // a fresh registration.
364	          this.creds = { ...(this.creds ?? { pdsUrl: this.pdsUrl }), revoked: true };
365	          saveCredentials(this.creds);
366	        }
367	        this.onboardingError = err.message;
368	        callbacks.onFailed(err);
369	      });
370	  }
371	
372	  /**
373	   * A live access token for tool calls. Re-exchanges the assertion when the
374	   * cached token is missing or within 30s of expiry.
375	   */
376	  async accessToken(): Promise<string> {
377	    if (this.creds?.revoked) throw new RevokedError();
378	    if (this.onboarding) {
379	      throw new Error(
380	        `Onboarding is not finished: ask the account owner to confirm claim code ` +
381	          `${this.onboarding.userCode} at ${this.onboarding.verificationUri} (or in the ` +
382	          `Obsign wallet), then try again.`,
383	      );
384	    }
385	    if (!this.creds?.assertion) {
386	      throw new Error(
387	        this.onboardingError
388	          ? `Onboarding failed: ${this.onboardingError}`
389	          : 'No credentials for this PDS yet — restart the MCP server to onboard.',
390	      );
391	    }
392	    if (!this.assertionValid()) throw new SessionExpiredError();
393	
394	    const now = Math.floor(Date.now() / 1000);
395	    if (this.creds.accessToken && (this.creds.accessTokenExpiresAt ?? 0) > now + 30) {
396	      return this.creds.accessToken;
397	    }
398	
399	    const discovery = await this.discovered();
400	    try {
401	      const token = await exchangeAssertion(
402	        discovery.tokenEndpoint,
403	        this.creds.assertion,
404	        this.pdsUrl,
405	      );
406	      this.creds.accessToken = token.accessToken;
407	      this.creds.accessTokenExpiresAt = now + token.expiresIn;
408	      this.creds.scopes = token.scope ? token.scope.split(' ') : this.creds.scopes;
409	      saveCredentials(this.creds);
410	      return token.accessToken;
411	    } catch (err) {
412	      if (err instanceof RevokedError) {
413	        this.creds.revoked = true;
414	        this.creds.accessToken = undefined;
415	        this.creds.accessTokenExpiresAt = undefined;
416	        saveCredentials(this.creds);
417	      }
418	      throw err;
419	    }
420	  }
421	
422	  /** The DID this session acts as, once onboarded. */
423	  did(): string | null {
424	    return this.creds?.did ?? null;
425	  }
426	
427	  scopes(): string[] {
428	    return this.creds?.scopes ?? [];
429	  }
430	
431	  /** Explicit user action: forget everything about this PDS. */
432	  reset(): void {
433	    clearCredentials(this.pdsUrl);
434	    this.creds = null;
435	    this.onboarding = null;
436	    this.onboardingError = null;
437	  }
438	}
