1	// Test runner: the PDS refuses a non-https public_url (RFC 8414), so the
2	// suite fronts it with a loopback TLS proxy. The proxy's self-signed cert must
3	// be trusted by every Node process in the test (Node reads NODE_EXTRA_CA_CERTS
4	// only at startup), hence this wrapper: generate the throwaway cert, then
5	// re-spawn the actual `node --test` run with it trusted.
6	
7	import { spawnSync } from 'node:child_process';
8	import * as fs from 'node:fs';
9	import * as os from 'node:os';
10	import * as path from 'node:path';
11	import { fileURLToPath } from 'node:url';
12	
13	const testDir = path.dirname(fileURLToPath(import.meta.url));
14	const tlsDir = fs.mkdtempSync(path.join(os.tmpdir(), 'custos-mcp-tls-'));
15	const keyFile = path.join(tlsDir, 'key.pem');
16	const certFile = path.join(tlsDir, 'cert.pem');
17	
18	const openssl = spawnSync(
19	  'openssl',
20	  [
21	    'req', '-x509', '-newkey', 'ec', '-pkeyopt', 'ec_paramgen_curve:P-256',
22	    '-keyout', keyFile, '-out', certFile, '-days', '7', '-nodes',
23	    '-subj', '/CN=custos-mcp-test',
24	    '-addext', 'subjectAltName=IP:127.0.0.1,DNS:localhost',
25	  ],
26	  { stdio: ['ignore', 'ignore', 'inherit'] },
27	);
28	if (openssl.status !== 0) {
29	  console.error('failed to generate the test TLS certificate (is openssl installed?)');
30	  process.exit(1);
31	}
32	
33	const result = spawnSync(
34	  process.execPath,
35	  ['--test', path.join(testDir, 'conformance.test.ts')],
36	  {
37	    stdio: 'inherit',
38	    env: {
39	      ...process.env,
40	      NODE_EXTRA_CA_CERTS: certFile,
41	      CUSTOS_MCP_TEST_TLS_DIR: tlsDir,
42	    },
43	  },
44	);
45	fs.rmSync(tlsDir, { recursive: true, force: true });
46	process.exit(result.status ?? 1);
