1	// Sidecar configuration. Everything comes from the environment. Two origins are
2	// load-bearing and distinct:
3	//
4	//   MCP_SIDECAR_PDS_ORIGIN   — where the sidecar reaches the PDS. In the
5	//     co-located hosted tier this is a Railway *private* address
6	//     (`http://pds.railway.internal:PORT`), never the public domain; the
7	//     private network keeps forwarded traffic off the public internet.
8	//   MCP_SIDECAR_PUBLIC_ORIGIN — the sidecar's own public URL
9	//     (`https://mcp.obsign.org`), advertised as the OAuth *resource* identifier
10	//     in the MCP-spec protected-resource metadata.
11	//
12	// The PDS origin is required and parse-fails loudly: silently defaulting to a
13	// public URL would send forwarded credentials over the wrong path.
14	
15	export interface SidecarConfig {
16	  /** Where the sidecar forwards XRPC calls to (private network in prod). */
17	  pdsOrigin: string;
18	  /**
19	   * The public Custos authorization-server origin advertised to MCP clients in
20	   * the protected-resource metadata. Distinct from `pdsOrigin`: the client
21	   * completes OAuth against this reachable public URL (`https://obsign.org`),
22	   * never the private `*.railway.internal` address the sidecar forwards to.
23	   */
24	  authServerOrigin: string;
25	  /** The sidecar's own public origin — the OAuth resource identifier. */
26	  publicOrigin: string;
27	  /** TCP port to listen on. Railway injects PORT; default 8080 for local runs. */
28	  port: number;
29	  /** MCP endpoint path. */
30	  mcpPath: string;
31	}
32	
33	function trimTrailingSlash(url: string): string {
34	  return url.replace(/\/+$/, '');
35	}
36	
37	function requireOrigin(env: NodeJS.ProcessEnv, name: string): string {
38	  const value = env[name];
39	  if (!value || !value.trim()) {
40	    throw new Error(
41	      `${name} is not set. The sidecar will not guess a PDS origin — in the ` +
42	        'co-located tier this is the PDS\'s private Railway address ' +
43	        '(e.g. http://pds.railway.internal:8080). See docs/deploy.md → "MCP sidecar".',
44	    );
45	  }
46	  let parsed: URL;
47	  try {
48	    parsed = new URL(value);
49	  } catch {
50	    throw new Error(`${name} is not a valid URL: ${JSON.stringify(value)}`);
51	  }
52	  return trimTrailingSlash(parsed.toString());
53	}
54	
55	/**
56	 * Parse the sidecar config from an environment. Exported (rather than reading
57	 * `process.env` at module scope) so tests can drive it with a hand-built env and
58	 * assert the fail-loud behavior without mutating the process.
59	 */
60	export function loadConfig(env: NodeJS.ProcessEnv = process.env): SidecarConfig {
61	  const pdsOrigin = requireOrigin(env, 'MCP_SIDECAR_PDS_ORIGIN');
62	  // The public origin defaults to the PDS origin only for local single-host
63	  // runs; a real deployment sets it to the sidecar's own domain.
64	  const publicOriginRaw = env.MCP_SIDECAR_PUBLIC_ORIGIN?.trim();
65	  const publicOrigin = publicOriginRaw
66	    ? trimTrailingSlash(new URL(publicOriginRaw).toString())
67	    : pdsOrigin;
68	
69	  // The authorization server clients reach is Custos's PUBLIC URL, never the
70	  // private forwarding address. It defaults to the PDS origin only when that
71	  // origin is already public (local single-host runs); a co-located deployment
72	  // whose PDS origin is `*.railway.internal` MUST set this to `https://obsign.org`.
73	  const authServerRaw = env.MCP_SIDECAR_AUTH_SERVER_ORIGIN?.trim();
74	  const authServerOrigin = authServerRaw
75	    ? trimTrailingSlash(new URL(authServerRaw).toString())
76	    : pdsOrigin;
77	
78	  const rawPort = env.PORT ?? env.MCP_SIDECAR_PORT;
79	  const port = rawPort ? Number(rawPort) : 8080;
80	  if (!Number.isInteger(port) || port <= 0 || port > 65535) {
81	    throw new Error(`PORT must be a valid TCP port, got ${JSON.stringify(rawPort)}`);
82	  }
83	
84	  return {
85	    pdsOrigin,
86	    authServerOrigin,
87	    publicOrigin,
88	    port,
89	    mcpPath: env.MCP_SIDECAR_PATH ?? '/mcp',
90	  };
91	}
