1	// The per-caller registry: the sidecar's replacement for the stdio server's
2	// singleton `AgentSession`. It tracks distinct authenticated callers (keyed by
3	// the forwarded token's subject) so a long-running process can bound and evict
4	// them — but it stores NO credential. Each `resolve` mints a fresh,
5	// request-scoped `ForwardingSession` bound to that request's token, so two
6	// concurrent requests (even from the same caller) get independent sessions and
7	// neither can observe, overwrite, or release the other's token. An
8	// unauthenticated request resolves to none. Nothing survives a restart (ADR-0024).
9	
10	import type { AuthInfo } from '@modelcontextprotocol/sdk/server/auth/types.js';
11	import { ForwardingSession, callerSubject } from './session.ts';
12	
13	/** Injected clock so tests drive idle eviction deterministically. */
14	export type Clock = () => number;
15	
16	export interface SessionRegistryOptions {
17	  /** PDS origin every forwarding session forwards to. */
18	  pdsOrigin: string;
19	  /** Evict a caller's tracking entry after this long without use (default 5 min). */
20	  idleTtlMs?: number;
21	  /** Hard cap on distinct tracked callers (default 10k). */
22	  maxCallers?: number;
23	  clock?: Clock;
24	}
25	
26	/** Per-caller bookkeeping. Deliberately holds NO credential — only liveness. */
27	interface CallerEntry {
28	  lastAccess: number;
29	}
30	
31	export class SessionRegistry {
32	  private readonly pdsOrigin: string;
33	  private readonly idleTtlMs: number;
34	  private readonly maxCallers: number;
35	  private readonly clock: Clock;
36	  private readonly callers = new Map<string, CallerEntry>();
37	
38	  constructor(options: SessionRegistryOptions) {
39	    this.pdsOrigin = options.pdsOrigin;
40	    this.idleTtlMs = options.idleTtlMs ?? 5 * 60_000;
41	    this.maxCallers = options.maxCallers ?? 10_000;
42	    this.clock = options.clock ?? (() => Date.now());
43	  }
44	
45	  /**
46	   * Mint the request-scoped forwarding session for a request's authenticated
47	   * caller. Returns `null` when the request carries no usable credential — the
48	   * caller is unauthenticated and no session is minted. For an authenticated
49	   * caller the returned session is FRESH per call and bound to this request's
50	   * token; the registry only records that the caller is live (for eviction and
51	   * metrics), never the credential itself.
52	   */
53	  resolve(authInfo: AuthInfo | undefined): ForwardingSession | null {
54	    const token = authInfo?.token;
55	    if (!token) return null;
56	
57	    this.evictIdle();
58	
59	    const key = callerSubject(token);
60	    if (!this.callers.has(key)) this.enforceCap();
61	    this.callers.set(key, { lastAccess: this.clock() });
62	
63	    return new ForwardingSession(this.pdsOrigin, token, authInfo.scopes);
64	  }
65	
66	  /** Number of live distinct callers (for tests/metrics). */
67	  size(): number {
68	    return this.callers.size;
69	  }
70	
71	  /** Forget every tracked caller — the whole in-memory state, e.g. on shutdown. */
72	  clear(): void {
73	    this.callers.clear();
74	  }
75	
76	  private evictIdle(): void {
77	    const cutoff = this.clock() - this.idleTtlMs;
78	    for (const [key, entry] of this.callers) {
79	      if (entry.lastAccess < cutoff) this.callers.delete(key);
80	    }
81	  }
82	
83	  /** When at capacity, drop the least-recently-seen caller to make room. */
84	  private enforceCap(): void {
85	    if (this.callers.size < this.maxCallers) return;
86	    let oldestKey: string | null = null;
87	    let oldest = Infinity;
88	    for (const [key, entry] of this.callers) {
89	      if (entry.lastAccess < oldest) {
90	        oldest = entry.lastAccess;
91	        oldestKey = key;
92	      }
93	    }
94	    if (oldestKey !== null) this.callers.delete(oldestKey);
95	  }
96	}
