// AC3.1 + AC3.2: `create_post`, called over the sidecar's Streamable-HTTP
// transport with a forwarded child token, publishes an app.bsky.feed.post to the
// CHILD agent's repo — attributed to the child's own DID, with the parent's repo
// untouched. This is the sovereign-child attribution guarantee (ADR-0023)
// composed with credential forwarding (ADR-0024), end to end.

import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { startE2eFixture, xrpcGet, type E2eFixture } from './e2e-fixture.ts';
import { toolJson } from './support.ts';

const POST_TEXT = 'hello from a sovereign child agent (hermetic e2e, MM-370)';

let fx: E2eFixture;

before(async () => {
  fx = await startE2eFixture();
});

after(async () => {
  await fx.close();
});

test('fixture smoke: PDS + parent + minted child + sidecar all stand up', async () => {
  assert.match(fx.child.did, /^did:plc:[a-z2-7]{24}$/);
  assert.notEqual(fx.child.did, fx.parent.did, 'the child is its own identity, not the parent');
  assert.ok(fx.child.identityAssertion, 'the mint returned the child capability');

  const health = await fetch(`${fx.sidecar.url}/healthz`);
  assert.equal(health.status, 200);

  // The child resolves as a first-class account on the PDS.
  const described = await xrpcGet(fx.pds.baseUrl, 'com.atproto.repo.describeRepo', {
    repo: fx.child.did,
  });
  assert.equal(described.handle, fx.child.handle);
});

test('AC3.1: create_post over the sidecar creates a readable record', async (t) => {
  const token = await fx.exchangeChildToken();
  const client = await fx.connect(token);
  t.after(() => client.close());

  // The forwarded token IS the child: the session the sidecar minted for this
  // request reports the child DID, not the parent's.
  const who = toolJson(await client.callTool({ name: 'whoami', arguments: {} }));
  assert.equal(who.did, fx.child.did);

  const result = await client.callTool({
    name: 'create_post',
    arguments: { text: POST_TEXT },
  });
  assert.notEqual(result.isError, true, `create_post failed: ${JSON.stringify(result.content)}`);
  const created = toolJson(result);
  assert.ok(created.uri, 'createRecord returned a record uri');
  assert.ok(created.cid, 'createRecord returned a record cid');

  const rkey = created.uri.split('/').pop()!;

  // Read it back over the sidecar (get_record defaults to the session DID)…
  const viaSidecar = toolJson(
    await client.callTool({
      name: 'get_record',
      arguments: { collection: 'app.bsky.feed.post', rkey },
    }),
  );
  assert.equal(viaSidecar.uri, created.uri);
  assert.equal(viaSidecar.value.text, POST_TEXT);

  // …and directly from the PDS, independent of the sidecar.
  const direct = await xrpcGet(fx.pds.baseUrl, 'com.atproto.repo.getRecord', {
    repo: fx.child.did,
    collection: 'app.bsky.feed.post',
    rkey,
  });
  assert.equal(direct.uri, created.uri);
  assert.equal(direct.value.text, POST_TEXT);
});

test('AC3.2: the post lives in the child repo; the parent repo is unchanged', async () => {
  // The record's at-uri names the CHILD's DID as the repo.
  const childPosts = await xrpcGet(fx.pds.baseUrl, 'com.atproto.repo.listRecords', {
    repo: fx.child.did,
    collection: 'app.bsky.feed.post',
  });
  assert.equal(childPosts.records.length, 1);
  assert.match(childPosts.records[0].uri, new RegExp(`^at://${fx.child.did}/`));

  const parentPosts = await xrpcGet(fx.pds.baseUrl, 'com.atproto.repo.listRecords', {
    repo: fx.parent.did,
    collection: 'app.bsky.feed.post',
  });
  assert.equal(parentPosts.records.length, 0, 'nothing was written to the parent repo');

  // The write was authorized by the forwarded child capability, and the audit
  // trail attributes it to the child's registration (visible to the parent).
  const audit = await fetch(
    `${fx.pds.baseUrl}/v1/agents/${fx.child.registrationId}/audit`,
    { headers: { authorization: `Bearer ${fx.parent.accessJwt}` } },
  );
  assert.equal(audit.status, 200);
  const events = ((await audit.json()) as { events: { eventType: string; did?: string }[] })
    .events;
  const write = events.find((event) => event.eventType === 'repo_write');
  assert.ok(write, 'the repo write left an audit event on the child registration');
  assert.equal(write.did, fx.child.did, 'the audit event is attributed to the child DID');
});

// AC3.3: a forwarded token whose scopes exclude the write is refused by the PDS
// with 403 InsufficientScope, and the sidecar relays a legible, scope-naming
// error — parity with the stdio server's `relayError` — never a stack trace.
//
// `[agent_auth] granted_scopes` has no env override, so the fixture narrows it
// through a pds.toml in the spawn dir: the child's capability (and therefore the
// exchanged token) carries a repo scope for a different collection, and the PDS
// — the sole authority on scopes (the sidecar never checks them, ADR-0024) —
// refuses the app.bsky.feed.post create.

import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { startE2eFixture, xrpcGet, type E2eFixture } from './e2e-fixture.ts';

// A valid granular grant that deliberately cannot create an app.bsky.feed.post.
const NARROW_SCOPE = 'repo:app.bsky.graph.follow?action=create';

let fx: E2eFixture;

before(async () => {
  fx = await startE2eFixture({ grantedScopes: ['atproto', NARROW_SCOPE] });
});

after(async () => {
  await fx.close();
});

test('AC3.3: an out-of-scope create_post relays 403 InsufficientScope legibly', async (t) => {
  assert.deepEqual(
    fx.child.scopes,
    ['atproto', NARROW_SCOPE],
    'the minted capability is clamped to the narrowed operator scopes',
  );

  const token = await fx.exchangeChildToken();
  const client = await fx.connect(token);
  t.after(() => client.close());

  const result = await client.callTool({
    name: 'create_post',
    arguments: { text: 'this write is outside the granted scopes' },
  });
  assert.equal(result.isError, true, 'the out-of-scope write is refused');

  const message = (result.content as { text: string }[])[0]!.text;
  assert.match(message, /InsufficientScope/, 'names the PDS refusal');
  assert.match(message, /Granted scopes:/, 'reports what the agent actually holds');
  assert.ok(message.includes(NARROW_SCOPE), 'the granted scope list is spelled out');
  assert.doesNotMatch(message, /\n\s+at /, 'no stack trace reaches the caller');

  // The refusal was clean: nothing landed in the child repo.
  const posts = await xrpcGet(fx.pds.baseUrl, 'com.atproto.repo.listRecords', {
    repo: fx.child.did,
    collection: 'app.bsky.feed.post',
  });
  assert.equal(posts.records.length, 0);
});

// AC3.4: revoking the child mid-session kills the delegated capability at the
// caller-facing surface, legibly, with no partial write.
//
// Revocation is enforced at the token-exchange boundary (AC1.7): flipping the
// registration to `revoked` makes the next jwt-bearer exchange fail with
// `access_denied`, while an already-issued access token remains valid until its
// 5-minute TTL lapses — the documented, deliberate revocation bound (see the
// jwt-bearer notes in crates/pds/AGENTS.md). A real caller's session re-exchanges
// the durable assertion for fresh short-lived tokens (exactly what the stdio
// AgentSession does), so the sequence a revoked caller experiences is: the
// refresh fails legibly naming the revocation, and with no forwardable
// credential the sidecar refuses the call legibly too — nothing is written.

import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import {
  startE2eFixture,
  xrpcGet,
  TokenExchangeError,
  type E2eFixture,
} from './e2e-fixture.ts';
import { toolJson } from './support.ts';

let fx: E2eFixture;

before(async () => {
  fx = await startE2eFixture();
});

after(async () => {
  await fx.close();
});

test('AC3.4: revocation mid-session fails the next call legibly, with no partial write', async (t) => {
  // One successful write first — the session is live and working.
  const token = await fx.exchangeChildToken();
  const client = await fx.connect(token);
  t.after(() => client.close());

  const first = await client.callTool({
    name: 'create_post',
    arguments: { text: 'posted before revocation' },
  });
  assert.notEqual(first.isError, true, `pre-revocation post failed: ${JSON.stringify(first.content)}`);
  const created = toolJson(first);

  // The parent revokes the child through the real Phase-1 surface.
  const revoked = await fetch(`${fx.pds.baseUrl}/agent/child/revoke`, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      authorization: `Bearer ${fx.parent.accessJwt}`,
    },
    body: JSON.stringify({ did: fx.child.did }),
  });
  assert.equal(revoked.status, 200);
  assert.equal(((await revoked.json()) as { status: string }).status, 'revoked');

  // The delegated capability is dead: the caller's next token refresh — the
  // step every session performs before forwarding — fails with a legible,
  // revocation-naming error, not a stack trace.
  await assert.rejects(
    fx.exchangeChildToken(),
    (err: unknown) => {
      assert.ok(err instanceof TokenExchangeError);
      assert.equal(err.code, 'access_denied');
      assert.match(err.message, /revoked/i, 'the refusal names the revocation');
      return true;
    },
  );

  // With no forwardable credential, the sidecar refuses the second create_post
  // legibly (it holds nothing on the caller's behalf to fall back to, ADR-0024).
  const bare = await fx.connect();
  t.after(() => bare.close());
  const second = await bare.callTool({
    name: 'create_post',
    arguments: { text: 'should never land' },
  });
  assert.equal(second.isError, true);
  const message = (second.content as { text: string }[])[0]!.text;
  assert.match(message, /not authenticated/, 'the refusal is legible');
  assert.match(message, /OAuth/, 'and points at the recovery path');
  assert.doesNotMatch(message, /\n\s+at /, 'no stack trace reaches the caller');

  // No partial write: the child repo holds exactly the pre-revocation post.
  const posts = await xrpcGet(fx.pds.baseUrl, 'com.atproto.repo.listRecords', {
    repo: fx.child.did,
    collection: 'app.bsky.feed.post',
  });
  assert.equal(posts.records.length, 1);
  assert.equal(posts.records[0].uri, created.uri);
});

